import React, { useState } from "react";
import {
  TextField,
  Button,
  Box,
  Select,
  MenuItem,
  Paper,
  Typography,
  IconButton,
} from "@mui/material";
import { AddCircleOutline, RemoveCircleOutline } from "@mui/icons-material";
import axios from "axios";

const ContactForm = () => {
  const [fields, setFields] = useState([
    { id: "1", Type: "input", value: "", label: "Name" },
  ]);
  const [selectedIndex, setSelectedIndex] = useState(null); // Track selected field for editing

  // Handle input changes
  const handleChange = (index, key, newValue) => {
    const updatedFields = [...fields];
    updatedFields[index] = { ...updatedFields[index], [key]: newValue };
    setFields(updatedFields);
  };

  // Add or Update Field
  const addOrUpdateField = () => {
    if (selectedIndex !== null) {
      // Editing existing field
      setSelectedIndex(null); // Reset selection after edit
    } else {
      // Adding new field
      setFields([...fields, { id: `${fields.length + 1}`, Type: "input", value: "", label: "" }]);
    }
  };

  // Remove a field
  const removeField = (index) => {
    const updatedFields = fields.filter((_, i) => i !== index);
    setFields(updatedFields);
    if (selectedIndex === index) setSelectedIndex(null); // Reset selected field if removed
  };

  // Submit form
  const handleSubmit = async () => {
    try {
      const response = await axios.post("http://localhost:5000/contact-form", fields);
      console.log("Form submitted:", response.data);
    } catch (error) {
      console.error("Error submitting form:", error);
    }
  };

  return (
    <Paper sx={{ p: 3, width: "100%", maxWidth: 500, mx: "auto" }}>
      <Typography variant="h6" gutterBottom>
        Dynamic Contact Form
      </Typography>

      {fields.map((field, index) => (
        <Box key={field.id} display="flex" flexDirection="column" gap={2} mb={2}>
          {/* Field Type Selection */}
          <Select
            value={field.Type}
            onChange={(e) => handleChange(index, "Type", e.target.value)}
            sx={{ minWidth: 120 }}
          >
            <MenuItem value="input">Input</MenuItem>
            <MenuItem value="textarea">Textarea</MenuItem>
            <MenuItem value="select">Dropdown</MenuItem>
          </Select>

          {/* Field Label */}
          <TextField
            fullWidth
            label="Label"
            variant="outlined"
            value={field.label}
            onChange={(e) => handleChange(index, "label", e.target.value)}
          />

          {/* Field Value */}
          <TextField
            label="Value"
            variant="outlined"
            value={field.value}
            onChange={(e) => handleChange(index, "value", e.target.value)}
          />

          <Box display="flex" justifyContent="space-between">
            <IconButton onClick={() => removeField(index)} color="error">
              <RemoveCircleOutline />
            </IconButton>
            <Button
              variant="outlined"
              onClick={() => setSelectedIndex(index)}
            >
              Edit
            </Button>
          </Box>
        </Box>
      ))}

      {/* Add or Update Field Button */}
      <Button onClick={addOrUpdateField} startIcon={<AddCircleOutline />} variant="outlined">
        {selectedIndex !== null ? "Update Field" : "Add Field"}
      </Button>

      {/* Submit Button */}
      <Button onClick={handleSubmit} variant="contained" color="primary" sx={{ mt: 2, ml: 2 }}>
        Submit
      </Button>
    </Paper>
  );
};

export default ContactForm;
